window.AUTH=window.AUTH||{};window.AUTH["17-949"]={"d":"17-949","id":"2018/17-949","n":"Sturgeon v. Frost","briefs":[{"k":"petitioner","label":"Brief of petitioner John Sturgeon","date":"2018-08-07","url":"https://www.supremecourt.gov/DocketPDF/17/17-949/58723/20180807172823056_17-949%20ts.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondents Bert Frost, et al.","date":"2018-09-11","url":"https://www.supremecourt.gov/DocketPDF/17/17-949/63412/20180911212445914_17-949bsUnitedStates.pdf","side":"res","n":103},{"k":"reply","label":"Reply of petitioner John Sturgeon","date":"2018-10-11","url":"https://www.supremecourt.gov/DocketPDF/17/17-949/66641/20181011171905718_17-949_Reply%20Brief.pdf","side":"pet","n":40}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-949_6kgn.pdf","tr":true,"items":[{"t":"case","label":"Alaska v. Babbitt (Katie John I)","cite":"72 F.3d 698","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/72/698/","op":1,"sum":"Explaining and adopting Secretary’s conclusion that “public lands” under ANLICA include waters in which the United States has “reserved water rights”.","sumSrc":"brief:1","by":{"0":"18, 19, 34","1":"10, 21, 38, 42"}},{"t":"case","label":"Alaska v. United States","cite":"201 F.3d 1154","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/201/1154/","by":{"0":"13"}},{"t":"case","label":"Alaska v. United States","cite":"545 U.S. 75","y":2005,"id":"2004/128-orig","sc":1,"sum":"The Court unanimously concluded that the Alexander Archipelago waters were not inland waters and thus belonged to the federal government.","sumSrc":"Oyez","by":{"0":"43","1":"54"}},{"t":"case","label":"Arizona v. California","cite":"373 U.S. 546","y":1963,"id":"1961/8_orig","sc":1,"sum":"This original suit was brought in this Court by the State of Arizona against the State of California and seven of its public agencies. Later Nevada, New Mexico, Utah and the United States became parties. The basic controversy is over how much water each State has a legal right to use out of the waters of the Colorado River and its tributaries. A Special Master appointed by the Court conducted a lengthy trial and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","1":"34","2":"18"}},{"t":"case","label":"Bulova Watch Co. v. United States","cite":"365 U.S. 753","y":1961,"id":"1960/241","sc":1,"sum":"When the Court of Claims has awarded a judgment against the United States to a taxpayer for an overpayment of excess profits taxes, plus interest thereon \"as provided by law,\" determination of the allowance of interest on so much of the overpayment as was attributable to an unused excess profits credit carry-back is governed by § 3771 (e) of the Internal Revenue Code of 1939, dealing specifically with interest on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4"}},{"t":"case","label":"Cappaert v. United States","cite":"426 U.S. 128","y":1976,"id":"1975/74-1107","sc":1,"op":4,"sum":"As of 1952 when the United States reserved Devil's Hole, it acquired by reservation water rights in unappropriated appurtenant water sufficient to maintain the level of the underground pool to preserve its scienStates et al., also on certiorari to the same court. CAPPAERT v. UNITED STATES tific value and thereby implement the Presidential Proclamation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 35, 38, 39","1":"19, 34, 35, 37","2":"18"}},{"t":"case","label":"City of Angoon v. Hodel","cite":"803 F.2d 1016","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/803/1016/","by":{"0":"18, 36"}},{"t":"case","label":"City of Angoon v. Marsh","cite":"749 F.2d 1413","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/749/1413/","by":{"0":"5"}},{"t":"case","label":"Doe v. Nat’l Bd. of Medical Examiners","cite":"199 F.3d 146","y":1999,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/199/146/","by":{"0":"42"}},{"t":"case","label":"Cited Authorities Page Fed. Power Comm’n v. Niagara Mohawk Power Corp.","cite":"347 U.S. 239","y":1954,"id":"scdb/1953-052","sc":1,"op":2,"by":{"0":"36","1":"18, 33, 36","2":"19"}},{"t":"case","label":"Florida Prepaid Postsecondary Educ. Expense Bd. v. College Savings Bank","cite":"527 U.S. 627","y":1999,"id":"1998/98-531","sc":1,"sum":"The Court reasoned that although the Fourteenth Amendment authorizes Congress to pass \"appropriate legislation\" to protect parties from being deprived of property without due process, this in itself does not permit the abrogation of state sovereign immunity.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"0":"32","1":"53","2":"22"}},{"t":"case","label":"John v. United States (Katie John II)","cite":"247 F.3d 1032","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/247/1032/","op":1,"by":{"0":"18, 19, 34"}},{"t":"case","label":"John v. United States (Katie John III)","cite":"720 F.3d 1214","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/720/1214/","op":1,"by":{"0":"18, 20, 34, 40"}},{"t":"case","label":"Martin v. Waddell’s Lessee","cite":"41 U.S. 367","y":1842,"id":"scdb/1842-008","sc":1,"sum":"Ejectment for one hundred acres of land, covered with' water,.in Raritan bay, in the township of Perth Amboy, in the state of New Jersey. The land claimed lies beneath the navigable waters of the Raritan river and bay, where the tide ebbs arjd flows; and the principal right in dispute was -the property in the oyster fisheries in the public rivers and bays of East New Jersey. The claim was made under the charters of …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"PPL Montana v. Montana","cite":"565 U.S. 576","y":2012,"id":"2011/10-218","sc":1,"op":2,"ar":2,"sum":"The Court held that the constitutional test for determining whether a section of a river is navigable for title purposes requires a trial court to determine whether the relevant stretch of the river was navigable at the time of statehood.","sumSrc":"Oyez","by":{"0":"21, 28, 36","1":"29, 46, 54","2":"15"}},{"t":"case","label":"RadLAX Gateway Hotel v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"0":"24, 42","2":"4"}},{"t":"case","label":"Ragsdale v. Wolverine World Wide, Inc.","cite":"535 U.S. 81","y":2002,"id":"2001/00-6029","sc":1,"sum":"The Court held that the regulation is contrary to the FMLA and beyond the Secretary of Labor's authority. Among other findings, Justice Kennedy reasoned that the regulation amended the FMLA's most fundamental substantive guarantee, the 12-week leave entitlement, and thus undermined Congress's balance of the needs of families and the interests of employers.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Cited Authorities Page Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"0":"32","1":"55"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"0":"1"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cty. v. U.S. Army Corps of Engineers","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"0":"32","1":"54","2":"22"}},{"t":"case","label":"Sturgeon v. Frost","cite":"136 S. Ct. 1061","y":2016,"id":"2015/14-1209","sc":1,"sum":"The Court held that the Alaska National Interest Lands Conservation Act of 1980 did not allow the National Park Service to regulate all land physically within the boundaries of the National Park System in Alaska.","sumSrc":"Oyez","by":{"0":"passim","2":"passim"}},{"t":"case","label":"Tarrant Reg’l Water Dist. v. Herrmann","cite":"569 U.S. 614","y":2013,"id":"2012/11-889","sc":1,"sum":"The Court held that Congress’ approval of an interstate water compact does not violate the Commerce Clause and that the compact does respect state lines.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Terry v. Terry","cite":"565 So. 2d 997","y":1990,"court":"La. App.","url":"https://www.courtlistener.com/c/So.%202d/565/997/","by":{"0":"36"}},{"t":"case","label":"Totemoff v. State","cite":"905 P.2d 954","y":1995,"court":"Alaska","url":"https://www.courtlistener.com/c/P.2d/905/954/","op":1,"by":{"0":"33","2":"19"}},{"t":"case","label":"Trustees for Alaska v. State","cite":"736 P.2d 324","y":1987,"court":"Alaska","url":"https://www.courtlistener.com/c/P.2d/736/324/","by":{"0":"3"}},{"t":"case","label":"United States v. Alaska","cite":"521 U.S. 1","y":1997,"id":"1996/84_orig","sc":1,"op":1,"sum":"The Court ruled that the federal government, the United States, owned the disputed submerged lands - adjacent to the National Wildlife Refuge and the National Petroleum Reserve - along Alaska's Arctic Coast.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"United States v. California","cite":"436 U.S. 32","y":1978,"id":"1977/5-orig","sc":1,"sum":"Writing for the majority, Justice Potter Stewart determined that under the Submerged Lands Act of 1953 after the 1947 United States v. California decision, Congress specified that the lands in dispute were under California's control.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"ix Cited Authorities Page United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"United States v. New Mexico","cite":"38 U.S. 696","y":1978,"id":"1977/77-510","sc":1,"sum":"The United States, in setting aside the Gila National Forest from other public lands, held to have reserved the use of water out of the Rio Mimbres only where necessary to preserve the timber in the forest or to secure favorable water flows, and hence not to have a reserved right for aesthetic, recreational, wildlife-preservation, and stockwatering purposes. That this was Congress' intent is revealed in the limited …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 38, 39","1":"19, 35"}},{"t":"case","label":"United States v. Virginia Elec. & Power Co.","cite":"365 U.S. 624","y":1961,"id":"1960/49","sc":1,"sum":"The Supreme Court held that the land the government was taking for easement had market value, and the Fifth Amendment prevents the government from taking private property without compensation. The Court also held that the district court’s method of determining the value of the land was correct, but the determination of how much of that compensation is due to the Virginia Electric Company was not correct.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Utility Air Regulatory Group v. EPA","cite":"134 S. Ct. 2427","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"const","label":"Article IV, Section 3, Clause 2","clauses":[["property-clause","Territory and Property Clause"]],"text":"The Congress shall have Power to dispose of and make all needful Rules and Regulations respecting the Territory or other Property belonging to the United States; and nothing in this Constitution shall be so construed as to Prejudice any Claims of the United States, or of any particular State.","by":{"0":"44"}},{"t":"usc","label":"16 U.S.C. § 17j-2","url":"https://www.law.cornell.edu/uscode/text/16/17j-2","subs":["(1976)"],"by":{"0":"39"}},{"t":"usc","label":"16 U.S.C. § 251n","url":"https://www.law.cornell.edu/uscode/text/16/251n","subs":["(a)(1)"],"by":{"0":"32"}},{"t":"usc","label":"16 U.S.C. § 410hh","url":"https://www.law.cornell.edu/uscode/text/16/410hh","subs":["(10)","(6)","(8)"],"stext":{"head":"§410hh. Establishment of new areas","paras":[[0,"The following areas are hereby established as units of the National Park System and shall be administered by the Secretary under the laws governing the administration of such lands and under the provisions of this Act:"],[1,"(1) Aniakchak National Monument, containing approximately one hundred and thirty-eight thousand acres of public lands, and Aniakchak National Preserve, containing approximately three hundred and seventy-six thousand acres of public lands, as generally depicted on map numbered ANIA–90,005, and dated October 1978. The monument and preserve shall be managed for the following purposes, among others: To maintain the caldera and its associated volcanic features and landscape, including the Aniakchak River and other lakes and streams, in their natural state; to study, interpret, and assure continuation of the natural process of biological succession; to protect habitat for, and populations of, fish and wildlife, including, but not limited to, brown/grizzly bears, moose, caribou, sea lions, seals, and other marine mammals, geese, swans, and other waterfowl and in a manner consistent with the foregoing, to interpret geological and biological processes for visitors. Subsistence uses by local residents shall be permitted in the monument where such uses are traditional in accordance with the provisions of subchapter II of chapter 51 of this title."],[1,"(2) Bering Land Bridge National Preserve, containing approximately two million four hundred and fifty-seven thousand acres of public land, as generally depicted on map numbered BELA–90,005, and dated October 1978. The preserve shall be managed for the following purposes, among others: To protect and interpret examples of arctic plant communities, volcanic lava flows, ash explosions, coastal formations, and other geologic processes; to protect habitat for internationally significant populations of migratory birds; to provide for archeological and paleontological study, in cooperation with Native Alaskans, of the process of plant and animal migration, including man, between North America and the Asian Continent; to protect habitat for, and populations of, fish and wildlife including, but not limited to, marine mammals, brown/grizzly bears, moose, and wolves; subject to such reasonable regulations as the Secretary may prescribe, to continue reindeer grazing use, including necessary facilities and equipment, within the areas which on January 1, 1976, were subject to reindeer grazing permits, in accordance with sound range management practices; to protect the viability of subsistence resources; and in a manner consistent with the foregoing, to provide for outdoor recreation and environmental education activities including public access for recreational purposes to the Serpentine Hot Springs area. The Secretary shall permit the continuation of customary patterns and modes of travel during periods of adequate snow cover within a one-hundred-foot right-of-way along either side of an existing route from Deering to the Taylor Highway, subject to such reasonable regulations as the Secretary may promulgate to assure that such travel is consistent with the foregoing purposes."],[1,"(3) Cape Krusenstern National Monument, containing approximately five hundred and sixty thousand acres of public lands, as generally depicted on map numbered CAKR–90,007, and dated October 1979. The monument shall be managed for the following purposes, among others: To protect and interpret a series of archeological sites depicting every known cultural period in arctic Alaska; to provide for scientific study of the process of human population of the area from the Asian Continent; in cooperation with Native Alaskans, to preserve and interpret evidence of prehistoric and historic Native cultures; to protect habitat for seals and other marine mammals; to protect habitat for and populations of, birds, and other wildlife, and fish resources; and to protect the viability of subsistence resources. Subsistence uses by local residents shall be permitted in the monument in accordance with the provisions of subchapter II of chapter 51 of this title."],[1,"(4)(a) Gates of the Arctic National Park, containing approximately seven million fifty-two thousand acres of public lands, Gates of the Arctic National Preserve, containing approximately nine hundred thousand acres of Federal lands, as generally depicted on map numbered GAAR–90,011, and dated July 1980. The park and preserve shall be managed for the following purposes, among others: To maintain the wild and undeveloped character of the area, including opportunities for visitors to experience solitude, and the natural environmental integrity and scenic beauty of the mountains, forelands, rivers, lakes, and other natural features; to provide continued opportunities, including reasonable access, for mountain climbing, mountaineering, and other wilderness recreational activities; and to protect habitat for and the populations of, fish and wildlife, including, but not limited to, caribou, grizzly bears, Dall sheep, moose, wolves, and raptorial birds. Subsistence uses by local residents shall be permitted in the park, where such uses are traditional, in accordance with the provisions of subchapter II of chapter 51 of this title."],[1,"(b) Congress finds that there is a need for access for surface transportation purposes across the Western (Kobuk River) unit of the Gates of the Arctic National Preserve (from the Ambler Mining District to the Alaska Pipeline Haul Road) and the Secretary shall permit such access in accordance with the provisions of this subsection."],[1,"(c) Upon the filing of an application pursuant to section 3164(b) and (c) of this title for a right-of-way across the Western (Kobuk River) unit of the preserve, including the Kobuk Wild and Scenic River, the Secretary shall give notice in the Federal Register of a thirty-day period for other applicants to apply for access."],[1,"(d) The Secretary and the Secretary of Transportation shall jointly prepare an environmental and economic analysis solely for the purpose of determining the most desirable route for the right-of-way and terms and conditions which may be required for the issuance of that right-of-way. This analysis shall be completed within one year and the draft thereof within nine months of the receipt of the application and shall be prepared in lieu of an environmental impact statement which would otherwise be required under section 102(2)(C) of the National Environmental Policy Act [42 U.S.C. 4332(2)(C)]. Such analysis shall be deemed to satisfy all requirements of that Act [42 U.S.C. 4321 et seq.] and shall not be subject to judicial review. Such environmental and economic analysis shall be prepared in accordance with the procedural requirements of section 3164(e) of this title. The Secretaries in preparing the analysis shall consider the following—"],[2,"(i) Alternative routes including the consideration of economically feasible and prudent alternative routes across the preserve which would result in fewer or less severe adverse impacts upon the preserve."],[2,"(ii) The environmental and social and economic impact of the right-of-way including impact upon wildlife, fish, and their habitat, and rural and traditional lifestyles including subsistence activities, and measures which should be instituted to avoid or minimize negative impacts and enhance positive impacts."],[1,"(e) Within 60 days of the completion of the environmental and economic analysis, the Secretaries shall jointly agree upon a route for issuance of the right-of-way across the preserve. Such right-of-way shall be issued in accordance with the provisions of section 3167 of this title."],[1,"(5) Kenai Fjords National Park, containing approximately five hundred and sixty-seven thousand acres of public lands, as generally depicted on map numbered KEFJ–90,007, and dated October 1978. The park shall be managed for the following purposes, among others: To maintain unimpaired the scenic and environmental integrity of the Harding Icefield, its outflowing glaciers, and coastal fjords and islands in their natural state; and to protect seals, sea lions, other marine mammals, and marine and other birds and to maintain their hauling and breeding areas in their natural state, free of human activity which is disruptive to their natural processes. In a manner consistent with the foregoing, the Secretary is authorized to develop access to the Harding Icefield and to allow use of mechanized equipment on the icefield for recreation."],[1,"(6) Kobuk Valley National Park, containing approximately one million seven hundred and ten thousand acres of public lands as generally depicted on map numbered KOVA–90,009, and dated October 1979. The park shall be managed for the following purposes, among others: To maintain the environmental integrity of the natural features of the Kobuk River Valley, including the Kobuk, Salmon, and other rivers, the boreal forest, and the Great Kobuk Sand Dunes, in an undeveloped state; to protect and interpret, in cooperation with Native Alaskans, archeological sites associated with Native cultures; to protect migration routes for the Arctic caribou herd; to protect habitat for, and populations of, fish and wildlife including but not limited to caribou, moose, black and grizzly bears, wolves, and waterfowl; and to protect the viability of subsistence resources. Subsistence uses by local residents shall be permitted in the park in accordance with the provisions of subchapter II of chapter 51 of this title. Except at such times when, and locations where, to do so would be inconsistent with the purposes of the park, the Secretary shall permit aircraft to continue to land at sites in the upper Salmon River watershed."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/410hh?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§410hh. Establishment of new areas","tname":"Conservation","by":{"0":"45, 13, 42","1":"6, 41, 6, 41, 7, 41, 6, 19, 35, 41","2":"3"}},{"t":"usc","label":"16 U.S.C. § 410hh-2","url":"https://www.law.cornell.edu/uscode/text/16/410hh-2","by":{"0":"31","1":"7, 21, 51"}},{"t":"usc","label":"16 U.S.C. § 410hh-4","url":"https://www.law.cornell.edu/uscode/text/16/410hh-4","by":{"0":"31"}},{"t":"usc","label":"16 U.S.C. § 539d","url":"https://www.law.cornell.edu/uscode/text/16/539d","by":{"0":"40"}},{"t":"usc","label":"16 U.S.C. § 3101","url":"https://www.law.cornell.edu/uscode/text/16/3101","subs":["(b)","(d)","(a)","(c)"],"stext":{"head":"§3101. Congressional statement of purpose","paras":[[0,"(a) Establishment of units"],[0,"In order to preserve for the benefit, use, education, and inspiration of present and future generations certain lands and waters in the State of Alaska that contain nationally significant natural, scenic, historic, archeological, geological, scientific, wilderness, cultural, recreational, and wildlife values, the units described in the following titles are hereby established."],[0,"(b) Preservation and protection of scenic, geological, etc., values"],[0,"It is the intent of Congress in this Act to preserve unrivaled scenic and geological values associated with natural landscapes; to provide for the maintenance of sound populations of, and habitat for, wildlife species of inestimable value to the citizens of Alaska and the Nation, including those species dependent on vast relatively undeveloped areas; to preserve in their natural state extensive unaltered arctic tundra, boreal forest, and coastal rainforest ecosystems; to protect the resources related to subsistence needs; to protect and preserve historic and archeological sites, rivers, and lands, and to preserve wilderness resource values and related recreational opportunities including but not limited to hiking, canoeing, fishing, and sport hunting, within large arctic and subarctic wildlands and on freeflowing rivers; and to maintain opportunities for scientific research and undisturbed ecosystems."],[0,"(c) Subsistence way of life for rural residents"],[0,"It is further the intent and purpose of this Act consistent with management of fish and wildlife in accordance with recognized scientific principles and the purposes for which each conservation system unit is established, designated, or expanded by or pursuant to this Act, to provide the opportunity for rural residents engaged in a subsistence way of life to continue to do so."],[0,"(d) Need for future legislation obviated"],[0,"This Act provides sufficient protection for the national interest in the scenic, natural, cultural and environmental values on the public lands in Alaska, and at the same time provides adequate opportunity for satisfaction of the economic and social needs of the State of Alaska and its people; accordingly, the designation and disposition of the public lands in Alaska pursuant to this Act are found to represent a proper balance between the reservation of national conservation system units and those public lands necessary and appropriate for more intensive use and disposition, and thus Congress believes that the need for future legislation designating new conservation system units, new national conservation areas, or new national recreation areas, has been obviated thereby."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/3101?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§3101. Congressional statement of purpose","tname":"Conservation","by":{"0":"5, 16, passim","1":"2, 11, 11, 11, 11, 11","2":"11, 12"}},{"t":"usc","label":"16 U.S.C. § 3102","url":"https://www.law.cornell.edu/uscode/text/16/3102","subs":["(1)","(2)","(3)","(3)(A)","(4)"],"stext":{"head":"§3102. Definitions","paras":[[0,"As used in this Act (except that in titles IX and XIV the following terms shall have the same meaning as they have in the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.], and the Alaska Statehood Act)—"],[1,"(1) The term \"land\" means lands, waters, and interests therein."],[1,"(2) The term \"Federal land\" means lands the title to which is in the United States after December 2, 1980."],[1,"(3) The term \"public lands\" means land situated in Alaska which, after December 2, 1980, are Federal lands, except—"],[2,"(A) land selections of the State of Alaska which have been tentatively approved or validly selected under the Alaska Statehood Act and lands which have been confirmed to, validly selected by, or granted to the Territory of Alaska or the State under any other provision of Federal law;"],[2,"(B) land selections of a Native Corporation made under the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.] which have not been conveyed to a Native Corporation, unless any such selection is determined to be invalid or is relinquished; and"],[2,"(C) lands referred to in section 19(b) of the Alaska Native Claims Settlement Act [43 U.S.C. 1618(b)]."],[1,"(4) The term \"conservation system unit\" means any unit in Alaska of the National Park System, National Wildlife Refuge System, National Wild and Scenic Rivers Systems, National Trails System, National Wilderness Preservation System, or a National Forest Monument including existing units, units established, designated, or expanded by or under the provisions of this Act, additions to such units, and any such unit established, designated, or expanded hereafter."],[1,"(5) The term \"Alaska Native Claims Settlement Act\" means \"An Act to provide for the settlement of certain land claims of Alaska Natives, and for other purposes\", approved December 18, 1971 (85 Stat. 688), as amended [43 U.S.C. 1601 et seq.]."],[1,"(6) The term \"Native Corporation\" means any Regional Corporation, any Village Corporation, any Urban Corporation, and any Native Group."],[1,"(7) The term \"Regional Corporation\" has the same meaning as such term has under section 3(g) of the Alaska Native Claims Settlement Act [43 U.S.C. 1602(g)]."],[1,"(8) The term \"Village Corporation\" has the same meaning as such term has under section 3(j) of the Alaska Native Claims Settlement Act [43 U.S.C. 1602(j)]."],[1,"(9) The term \"Urban Corporation\" means those Native entities which have incorporated pursuant to section 14(h)(3) of the Alaska Native Claims Settlement Act [43 U.S.C. 1613(h)(3)]."],[1,"(10) The term \"Native Group\" has the same meaning as such term has under sections 3(d) and 14(h)(2) of the Alaska Native Claims Settlement Act [43 U.S.C. 1602(d) and 1613(h)(2)]."],[1,"(11) The term \"Native land\" means land owned by a Native Corporation or any Native Group and includes land which, as of December 2, 1980, had been selected under the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.] by a Native Corporation or Native Group and had not been conveyed by the Secretary (except to the extent such selection is determined to be invalid or has been relinquished) and land referred to in section 19(b) of the Alaska Native Claims Settlement Act [43 U.S.C. 1618(b)]."],[1,"(12) The term \"Secretary\" means the Secretary of the Interior, except that when such term is used with respect to any unit of the National Forest System, such term means the Secretary of Agriculture."],[1,"(13) The terms \"wilderness\" and \"National Wilderness Preservation System\" have the same meaning as when used in the Wilderness Act (78 Stat. 890) [16 U.S.C. 1131 et seq.]."],[1,"(14) The term \"Alaska Statehood Act\" means the Act entitled \"An Act to provide for the admission of the State of Alaska into the Union\", approved July 7, 1958 (72 Stat. 339), as amended."],[1,"(15) The term \"State\" means the state of Alaska."],[1,"(16) The term \"Alaska Native\" or \"Native\" has the same meaning as the term \"Native\" has in section 3(b) of the Alaska Native Claims Settlement Act [43 U.S.C. 1602(b)]."],[1,"(17) The term \"fish and wildlife\" means any member of the animal kingdom, including without limitation any mammal, fish, bird (including any migratory, nonmigratory or endangered bird for which protection is also afforded by treaty or other international agreement), amphibian, reptile, mollusk, crustacean, arthropod or other invertebrate, and includes any part, product, egg, or offspring thereof, or the dead body or part thereof."],[1,"(18) The term \"take\" or \"taking\" as used with respect to fish or wildlife, means to pursue, hunt, shoot, trap, net capture, collect, kill, harm, or attempt to engage in any such conduct."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/3102?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3102. Definitions","tname":"Conservation","by":{"0":"1, 7, 26, passim, passim, 33, 6, 7","1":"11, 11, 11, 11","2":"passim"}},{"t":"usc","label":"16 U.S.C. § 3103","url":"https://www.law.cornell.edu/uscode/text/16/3103","subs":["(b)","(c)","(a)"],"stext":{"head":"§3103. Maps","paras":[[0,"(a) Filing and availability for inspection; discrepancies; coastal areas"],[0,"The boundary maps described in this Act shall be on file and available for public inspection in the office of the Secretary or the Secretary of Agriculture with regard to the National Forest System. In the event of discrepancies between the acreages specified in this Act and those depicted on such maps, the maps shall be controlling, but the boundaries of areas added to the National Park, Wildlife Refuge and National Forest Systems shall, in coastal areas not extend seaward beyond the mean high tide line to include lands owned by the State of Alaska unless the State shall have concurred in such boundary extension and such extension is accomplished under the notice and reporting requirements of this Act."],[0,"(b) Changes in land management status; publication in Federal Register; filing; clerical errors; boundary features and adjustments"],[0,"As soon as practicable after December 2, 1980, a map and legal description of each change in land management status effected by this Act, including the National Wilderness Preservation System, shall be published in the Federal Register and filed with the Speaker of the House of Representatives and the President of the Senate, and each such description shall have the same force and effect as if included in this Act: Provided, however, That correction of clerical and typographical errors in each such legal description and map may be made. Each such map and legal description shall be on file and available for public inspection in the office of the Secretary. Whenever possible boundaries shall follow hydrographic divides or embrace other topographic or natural features. Following reasonable notice in writing to the Congress of his intention to do so the Secretary and the Secretary of Agriculture may make minor adjustments in the boundaries of the areas added to or established by this Act as units of National Park, Wildlife Refuge, Wild and Scenic Rivers, National Wilderness Preservation, and National Forest Systems and as national conservation areas and national recreation areas. For the purposes of this subsection, a minor boundary adjustment shall not increase or decrease the amount of land within any such area by more than 23,000 acres."],[0,"(c) Lands included within unit; acquisition of land by Secretary"],[0,"Only those lands within the boundaries of any conservation system unit which are public lands (as such term is defined in this Act) shall be deemed to be included as a portion of such unit. No lands which, before, on, or after December 2, 1980, are conveyed to the State, to any Native Corporation, or to any private party shall be subject to the regulations applicable solely to public lands within such units. If the State, a Native Corporation, or other owner desires to convey any such lands, the Secretary may acquire such lands in accordance with applicable law (including this Act), and any such lands shall become part of the unit, and be administered accordingly."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/3103?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§3103. Maps","tname":"Conservation","by":{"0":"6, 30, passim","1":"41, 41, 41, 41","2":"passim"}},{"t":"usc","label":"16 U.S.C. § 3111","url":"https://www.law.cornell.edu/uscode/text/16/3111","subs":["(2)","(4)","(1)"],"stext":{"head":"§3111. Congressional declaration of findings","paras":[[0,"The Congress finds and declares that—"],[1,"(1) the continuation of the opportunity for subsistence uses by rural residents of Alaska, including both Natives and non-Natives, on the public lands and by Alaska Natives on Native lands is essential to Native physical, economic, traditional, and cultural existence and to non-Native physical, economic, traditional, and social existence;"],[1,"(2) the situation in Alaska is unique in that, in most cases, no practical alternative means are available to replace the food supplies and other items gathered from fish and wildlife which supply rural residents dependent on subsistence uses;"],[1,"(3) continuation of the opportunity for subsistence uses of resources on public and other lands in Alaska is threatened by the increasing population of Alaska, with resultant pressure on subsistence resources, by sudden decline in the populations of some wildlife species which are crucial subsistence resources, by increased accessibility of remote areas containing subsistence resources, and by taking of fish and wildlife in a manner inconsistent with recognized principles of fish and wildlife management;"],[1,"(4) in order to fulfill the policies and purposes of the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.] and as a matter of equity, it is necessary for the Congress to invoke its constitutional authority over Native affairs and its constitutional authority under the property clause and the commerce clause to protect and provide the opportunity for continued subsistence uses on the public lands by Native and non-Native rural residents; and"],[1,"(5) the national interest in the proper regulation, protection, and conservation of fish and wildlife on the public lands in Alaska and the continuation of the opportunity for a subsistence way of life by residents of rural Alaska require that an administrative structure be established for the purpose of enabling rural residents who have personal knowledge of local conditions and requirements to have a meaningful role in the management of fish and wildlife and of subsistence uses on the public lands in Alaska."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/3111?type=usc&year=mostrecent&link-type=html"},"head":"§3111. Congressional declaration of findings","tname":"Conservation","by":{"0":"16, 33, 44","1":"41, 42"}},{"t":"usc","label":"16 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/16/3142","by":{"0":"40"}},{"t":"usc","label":"16 U.S.C. § 3147","url":"https://www.law.cornell.edu/uscode/text/16/3147","subs":["(b)(5)"],"by":{"0":"16"}},{"t":"usc","label":"16 U.S.C. § 3192","url":"https://www.law.cornell.edu/uscode/text/16/3192","by":{"0":"39"}},{"t":"usc","label":"16 U.S.C. § 3202","url":"https://www.law.cornell.edu/uscode/text/16/3202","subs":["(a)","(b)"],"by":{"0":"31, 34, 34","1":"47"}},{"t":"usc","label":"16 U.S.C. § 3207","url":"https://www.law.cornell.edu/uscode/text/16/3207","subs":["(2)","(3)"],"by":{"0":"33","1":"45, 45, 46, 46"}},{"t":"usc","label":"16 U.S.C. § 3209","url":"https://www.law.cornell.edu/uscode/text/16/3209","subs":["(a)"],"by":{"0":"5"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"43 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/43/1311","subs":["(a)"],"stext":{"head":"§1311. Rights of States","paras":[[0,"(a) Confirmation and establishment of title and ownership of lands and resources; management, administration, leasing, development, and use"],[0,"It is determined and declared to be in the public interest that (1) title to and ownership of the lands beneath navigable waters within the boundaries of the respective States, and the natural resources within such lands and waters, and (2) the right and power to manage, administer, lease, develop, and use the said lands and natural resources all in accordance with applicable State law be, and they are, subject to the provisions hereof, recognized, confirmed, established, and vested in and assigned to the respective States or the persons who were on June 5, 1950, entitled thereto under the law of the respective States in which the land is located, and the respective grantees, lessees, or successors in interest thereof;"],[0,"(b) Release and relinquishment of title and claims of United States; payment to States of moneys paid under leases"],[0,"(1) The United States releases and relinquishes unto said States and persons aforesaid, except as otherwise reserved herein, all right, title, and interest of the United States, if any it has, in and to all said lands, improvements, and natural resources; (2) the United States releases and relinquishes all claims of the United States, if any it has, for money or damages arising out of any operations of said States or persons pursuant to State authority upon or within said lands and navigable waters; and (3) the Secretary of the Interior or the Secretary of the Navy or the Treasurer of the United States shall pay to the respective States or their grantees issuing leases covering such lands or natural resources all moneys paid thereunder to the Secretary of the Interior or to the Secretary of the Navy or to the Treasurer of the United States and subject to the control of any of them or to the control of the United States on May 22, 1953, except that portion of such moneys which (1) is required to be returned to a lessee; or (2) is deductible as provided by stipulation or agreement between the United States and any of said States;"],[0,"(c) Leases in effect on June 5, 1950"],[0,"The rights, powers, and titles hereby recognized, confirmed, established, and vested in and assigned to the respective States and their grantees are subject to each lease executed by a State, or its grantee, which was in force and effect on June 5, 1950, in accordance with its terms and provisions and the laws of the State issuing, or whose grantee issued, such lease, and such rights, powers, and titles are further subject to the rights herein now granted to any person holding any such lease to continue to maintain the lease, and to conduct operations thereunder, in accordance with its provisions, for the full term thereof, and any extensions, renewals, or replacements authorized therein, or heretofore authorized by the laws of the State issuing, or whose grantee issued such lease: Provided, however, That, if oil or gas was not being produced from such lease on and before December 11, 1950, or if the primary term of such lease has expired since December 11, 1950, then for a term from May 22, 1953 equal to the term remaining unexpired on December 11, 1950, under the provisions of such lease or any extensions, renewals, or replacements authorized therein, or heretofore authorized by the laws of the State issuing, or whose grantee issued, such lease: Provided, however, That within ninety days from May 22, 1953 (i) the lessee shall pay to the State or its grantee issuing such lease all rents, royalties, and other sums payable between June 5, 1950, and May 22, 1953, under such lease and the laws of the State issuing or whose grantee issued such lease, except such rents, royalties, and other sums as have been paid to the State, its grantee, the Secretary of the Interior or the Secretary of the Navy or the Treasurer of the United States and not refunded to the lessee; and (ii) the lessee shall file with the Secretary of the Interior or the Secretary of the Navy and with the State issuing or whose grantee issued such lease, instruments consenting to the payment by the Secretary of the Interior or the Secretary of the Navy or the Treasurer of the United States to the State or its grantee issuing the lease, of all rents, royalties, and other payments under the control of the Secretary of the Interior or the Secretary of the Navy or the Treasurer of the United States or the United States which have been paid, under the lease, except such rentals, royalties, and other payments as have also been paid by the lessee to the State or its grantee;"],[0,"(d) Authority and rights of United States respecting navigation, flood control and production of power"],[0,"Nothing in this subchapter or subchapter I shall affect the use, development, improvement, or control by or under the constitutional authority of the United States of said lands and waters for the purposes of navigation or flood control or the production of power, or be construed as the release or relinquishment of any rights of the United States arising under the constitutional authority of Congress to regulate or improve navigation, or to provide for flood control, or the production of power;"],[0,"(e) Ground and surface waters west of 98th meridian"],[0,"Nothing in this subchapter or subchapter I shall be construed as affecting or intended to affect or in any way interfere with or modify the laws of the States which lie wholly or in part westward of the ninety-eighth meridian, relating to the ownership and control of ground and surface waters; and the control, appropriation, use, and distribution of such waters shall continue to be in accordance with the laws of such States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/43/1311?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1311. Rights of States","tname":"Public Lands","by":{"0":"14, 27, 28, 33","1":"33, 4"}},{"t":"usc","label":"43 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/43/1601","subs":["(a)"],"stext":{"head":"§1601. Congressional findings and declaration of policy","paras":[[0,"Congress finds and declares that—"],[1,"(a) there is an immediate need for a fair and just settlement of all claims by Natives and Native groups of Alaska, based on aboriginal land claims;"],[1,"(b) the settlement should be accomplished rapidly, with certainty, in conformity with the real economic and social needs of Natives, without litigation, with maximum participation by Natives in decisions affecting their rights and property, without establishing any permanent racially defined institutions, rights, privileges, or obligations, without creating a reservation system or lengthy wardship or trusteeship, and without adding to the categories of property and institutions enjoying special tax privileges or to the legislation establishing special relationships between the United States Government and the State of Alaska;"],[1,"(c) no provision of this chapter shall replace or diminish any right, privilege, or obligation of Natives as citizens of the United States or of Alaska, or relieve, replace, or diminish any obligation of the United States or of the State or 1 Alaska to protect and promote the rights or welfare of Natives as citizens of the United States or of Alaska; the Secretary is authorized and directed, together with other appropriate agencies of the United States Government, to make a study of all Federal programs primarily designed to benefit Native people and to report back to the Congress with his recommendations for the future management and operation of these programs within three years of December 18, 1971;"],[1,"(d) no provision of this chapter shall constitute a precedent for reopening, renegotiating, or legislating upon any past settlement involving land claims or other matters with any Native organizations, or any tribe, band, or identifiable group of American Indians;"],[1,"(e) no provision of this chapter shall effect a change or changes in the petroleum reserve policy reflected in sections 8721 through 8738 of title 10 except as specifically provided in this chapter;"],[1,"(f) no provision of this chapter shall be construed to constitute a jurisdictional act, to confer jurisdiction to sue, nor to grant implied consent to Natives to sue the United States or any of its officers with respect to the claims extinguished by the operation of this chapter; and"],[1,"(g) no provision of this chapter shall be construed to terminate or otherwise curtail the activities of the Economic Development Administration or other Federal agencies conducting loan or loan and grant programs in Alaska. For this purpose only, the terms \"Indian reservation\" and \"trust or restricted Indian-owned land areas\" in Public Law 89–136, the Public Works and Economic Development Act of 1965, as amended [42 U.S.C. 3121 et seq.], shall be interpreted to include lands granted to Natives under this chapter as long as such lands remain in the ownership of the Native villages or the Regional Corporations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/43/1601?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1601. Congressional findings and declaration of policy","tname":"Public Lands","by":{"0":"4","1":"4, 4"}},{"t":"usc","label":"43 U.S.C. § 1607","url":"https://www.law.cornell.edu/uscode/text/43/1607","by":{"0":"4"}},{"t":"usc","label":"43 U.S.C. § 1616","url":"https://www.law.cornell.edu/uscode/text/43/1616","subs":["(d)(2)","(d)(2)(A)","(d)(2)(D)"],"by":{"0":"4","1":"5, 5"}},{"t":"usc","label":"54 U.S.C. § 100101","url":"https://www.law.cornell.edu/uscode/text/54/100101","subs":["(a)"],"stext":{"head":"§100101. Promotion and regulation","paras":[[0,"(a) In General.—The Secretary, acting through the Director of the National Park Service, shall promote and regulate the use of the National Park System by means and measures that conform to the fundamental purpose of the System units, which purpose is to conserve the scenery, natural and historic objects, and wild life in the System units and to provide for the enjoyment of the scenery, natural and historic objects, and wild life in such manner and by such means as will leave them unimpaired for the enjoyment of future generations."],[0,"(b) Declarations.—"],[1,"(1) 1970 declarations.—Congress declares that—"],[2,"(A) the National Park System, which began with establishment of Yellowstone National Park in 1872, has since grown to include superlative natural, historic, and recreation areas in every major region of the United States and its territories and possessions;"],[2,"(B) these areas, though distinct in character, are united through their interrelated purposes and resources into one National Park System as cumulative expressions of a single national heritage;"],[2,"(C) individually and collectively, these areas derive increased national dignity and recognition of their superb environmental quality through their inclusion jointly with each other in one System preserved and managed for the benefit and inspiration of all the people of the United States; and"],[2,"(D) it is the purpose of this division to include all these areas in the System and to clarify the authorities applicable to the System."],[1,"(2) 1978 reaffirmation.—Congress reaffirms, declares, and directs that the promotion and regulation of the various System units shall be consistent with and founded in the purpose established by subsection (a), to the common benefit of all the people of the United States. The authorization of activities shall be construed and the protection, management, and administration of the System units shall be conducted in light of the high public value and integrity of the System and shall not be exercised in derogation of the values and purposes for which the System units have been established, except as directly and specifically provided by Congress."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/54/100101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§100101. Promotion and regulation","tname":"National Park Service and Related Programs","by":{"0":"37","1":"25"}},{"t":"usc","label":"54 U.S.C. § 100751","url":"https://www.law.cornell.edu/uscode/text/54/100751","subs":["(a)","(b)"],"stext":{"head":"§100751. Regulations","paras":[[0,"(a) In General.—The Secretary shall prescribe such regulations as the Secretary considers necessary or proper for the use and management of System units."],[0,"(b) Boating and Other Activities on or Relating to Water.—The Secretary, under such terms and conditions as the Secretary considers advisable, may prescribe regulations under subsection (a) concerning boating and other activities on or relating to water located within System units, including water subject to the jurisdiction of the United States. Any regulation under this subsection shall be complementary to, and not in derogation of, the authority of the Coast Guard to regulate the use of water subject to the jurisdiction of the United States."],[0,"(c) Criminal Penalties.—Criminal penalties for a violation of a regulation prescribed under this section are provided by section 1865 of title 18."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/54/100751?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§100751. Regulations","tname":"National Park Service and Related Programs","by":{"0":"15, 16, 25, 42, passim","1":"25, 25","2":"2, 5, 6, 8"}},{"t":"reg","label":"36 C.F.R. § 1.2","url":"https://www.ecfr.gov/current/title-36/section-1.2","subs":["(a)(3)","(b)"],"by":{"0":"12, 15, 12, 15, 10"}},{"t":"reg","label":"36 C.F.R. § 1.4","url":"https://www.ecfr.gov/current/title-36/section-1.4","by":{"0":"11"}},{"t":"reg","label":"36 C.F.R. § 2.17","url":"https://www.ecfr.gov/current/title-36/section-2.17","subs":["(e)"],"by":{"0":"12, 15"}},{"t":"reg","label":"36 C.F.R. pt. 13","url":"https://www.ecfr.gov/current/title-36/part-13","by":{"0":"12"}},{"t":"reg","label":"46 Fed. Reg. 31836","url":"https://www.govinfo.gov/link/fr/46/31836","by":{"0":"10"}},{"t":"reg","label":"52 Fed. Reg. 35239","url":"https://www.govinfo.gov/link/fr/52/35239","by":{"0":"11"}},{"t":"reg","label":"61 Fed. Reg. 35136","url":"https://www.govinfo.gov/link/fr/61/35136","by":{"0":"12"}},{"t":"case","label":"Amoco Prod. Co. v. Village of Gambell","cite":"480 U.S. 531","y":1987,"id":"1986/85-1239","sc":1,"ar":2,"sum":"Section 810(a) of the Alaska National Interest Lands Conservation Act (ANILCA) provides, inter alia, that, before allowing the use, occupancy, or disposition of public lands that would significantly restrict Alaskan Natives' use of those lands for subsistence, the head of the federal agency having primary jurisdiction over the lands must give notice, conduct a hearing, and determine that the restriction of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33, 49","2":"14, 17, 21"}},{"t":"case","label":"Commodity Futures Trading Comm’n v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 39","2":"16"}},{"t":"case","label":"Coventry Health Care of Mo., Inc. v. Nevils","cite":"137 S. Ct. 1190","y":2017,"id":"2016/16-149","sc":1,"sum":"The Court determined that the Federal Employees Health Benefits Act (FEHBA) preempts state laws that prohibit insurance companies from claiming the proceeds of personal injury settlements pursuant to their contracts, and the express preemption clause of the FEHBA does not violate the Supremacy Clause.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Crum v. Mt. Shasta Power Corp.","cite":"30 P.2d 30","y":1934,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/30/30/","op":1,"by":{"1":"36","2":"19"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Ingersoll-Rand Co. v. McClendon","cite":"498 U.S. 133","y":1990,"id":"1990/89-1298","sc":1,"sum":"ERISA's explicit language and its structure and purpose demonstrate a congressional intent to pre-empt a state common law claim that an employee was unlawfully discharged to prevent his attainment of benefits under an ERISA-covered plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28, 29"}},{"t":"case","label":"Kaiser Aetna v. United States","cite":"444 U.S. 164","y":1979,"id":"1979/78-738","sc":1,"op":1,"sum":"If the Government wishes to make what was formerly Kuapa Pond into a public aquatic park after petitioners have proceeded as far as they have here, it may not, without invoking its eminent domain power and paying just compensation, require them to allow the public free access to the dredged pond. Although the dredged pond falls within KAISER AETNA v. UNITED STATES","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"54"}},{"t":"case","label":"Kleppe v. New Mexico","cite":"426 U.S. 529","y":1976,"id":"1975/74-1488","sc":1,"op":4,"sum":"As applied to this case, the Act is a constitutional exercise of congressional power under the Property Clause of the Constitution, which.provides that \"Congress shall have Power to dispose of and make all needful Rules and Regulations respecting the Territory or other Property belonging to the United States.\" Art. IV, § 3, cl2..","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"sum":"The Court decided that a statement regarding a specific asset can be a “statement respecting the debtor’s . . . financial condition” under section 523(a)(2)(B) of the Bankruptcy Code.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"1":"56"}},{"t":"case","label":"Radcliff ’s Ex’rs v. The Mayor","cite":"4 N.Y. 195","y":1850,"url":"https://www.courtlistener.com/c/N.Y./4/195/","op":1,"sum":"Stating that an action is available against a person who diverts water “without having title to any thing more than the usufruct”.","sumSrc":"brief:1","by":{"1":"36","2":"19"}},{"t":"case","label":"Roberts v. Sea-Land Servs., Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Tee-Hit-Ton Indians v. United States","cite":"348 U.S. 272","y":1955,"id":"scdb/1954-029","sc":1,"sum":"The Tee-Hit-Ton Indians, an identifiable group of American Indians belonging to the Tlingit Tribe of Alaskan Indians, held not entitled to compensation under the Fifth Amendment for the taking by the United States of certain timber from Alaskan lands in and near the Tongass National Forest allegedly belonging to the Tee-Hit-Ton Indians.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4"}},{"t":"case","label":"United States v. Gerlach Live Stock Co.","cite":"339 U.S. 725","y":1950,"id":"scdb/1949-090","sc":1,"sum":"Judgments of the Court of Claims in favor of respondents are affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"United States v. Rands","cite":"389 U.S. 121","y":1967,"id":"1967/54","sc":1,"op":1,"sum":"Respondents owned land along the Columbia River in Oregon which the United States condemned in connection with a lock and dam project. In the condemnation action the trial court allowed compensation for sand, gravel, and agricultural purposes, but not for the land's special value as a port site. The Court of Appeals reversed, holding that exclusion of the port-site value of respondents' land contravened the Fifth …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"54"}},{"t":"case","label":"United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"sum":"The Clean Water Act prohibits any discharge of dredged or fill materials into \"navigable waters\"-defined as the \"waters of the United States\"unless authorized by a permit issued by the Army Corps of Engineers (Corps). Construing the Act to cover all \"freshwater wetlands\" that are adjacent to other covered waters, the Corps issued a regulation defining such wetlands as \"those areas that are inundated or saturated by …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"55"}},{"t":"case","label":"United States v. Wilde","cite":"2013 WL 6237704","y":2013,"court":"D. Alaska Dec. 3","sum":"Noting that Yukon River is navigable.","sumSrc":"brief:1","by":{"1":"44"}},{"t":"case","label":"Utilities Air Regulatory Grp. v. EPA","cite":"134 S. Ct. 2427","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2427/","sc":1,"by":{"1":"49","2":"10, 20"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"Winters v. United States","cite":"207 U.S. 564","y":1908,"id":"scdb/1907-046","sc":1,"op":2,"sum":"The rule that all the parties must join in an appeal or writ of error unless properly detached from the right so to do applies only to joint judgments and decrees. This court has jurisdiction of an appeal taken or writ of error sued out by one of several defendants if his interest is separate from that of the other defendants.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"34"}},{"t":"const","label":"Article IV, Clause 2","by":{"1":"32"}},{"t":"law","label":"Pub. L. No. 94-458","url":"https://www.govinfo.gov/link/statute/90/1939","by":{"1":"7, 27"}},{"t":"usc","label":"16 U.S.C. § 410hh-1","url":"https://www.law.cornell.edu/uscode/text/16/410hh-1","subs":["(1)"],"by":{"1":"6, 19, 35, 41, 41"}},{"t":"usc","label":"16 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/16/1110","subs":["(a)"],"by":{"1":"7"}},{"t":"usc","label":"16 U.S.C. § 3113","url":"https://www.law.cornell.edu/uscode/text/16/3113","subs":["(c)"],"by":{"1":"41, 42, 20"}},{"t":"usc","label":"16 U.S.C. § 3114","url":"https://www.law.cornell.edu/uscode/text/16/3114","by":{"1":"7, 21, 42"}},{"t":"usc","label":"16 U.S.C. § 3115","url":"https://www.law.cornell.edu/uscode/text/16/3115","subs":["(d)"],"by":{"1":"7, 10, 39"}},{"t":"usc","label":"16 U.S.C. § 3121","url":"https://www.law.cornell.edu/uscode/text/16/3121","stext":{"head":"§3121. Rural residents engaged in subsistence uses","paras":[[0,"(a) Access to subsistence resources"],[0,"The Secretary shall ensure that rural residents engaged in subsistence uses shall have reasonable access to subsistence resources on the public lands."],[0,"(b) Use of snowmobiles, motorboats, or other means of surface transportation"],[0,"Notwithstanding any other provision of this Act or other law, the Secretary shall permit on the public lands appropriate use for subsistence purposes of snowmobiles, motorboats, and other means of surface transportation traditionally employed for such purposes by local residents, subject to reasonable regulation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/3121?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3121. Rural residents engaged in subsistence uses","tname":"Conservation","by":{"1":"7, 43"}},{"t":"usc","label":"16 U.S.C. § 3170","url":"https://www.law.cornell.edu/uscode/text/16/3170","by":{"1":"7, 43"}},{"t":"usc","label":"16 U.S.C. § 3191","url":"https://www.law.cornell.edu/uscode/text/16/3191","subs":["(a)","(b)(7)"],"stext":{"head":"§3191. Management plans","paras":[[0,"(a) Development; transmittal to Congressional committees"],[0,"Within five years from December 2, 1980, the Secretary shall develop and transmit to the appropriate Committees of the Congress a conservation and management plan for each of the units of the National Park System established or to which additions are made by this Act."],[0,"(b) National Park service plan requirements"],[0,"Each plan for a unit established, redesignated, or expanded by subchapter LIX–F of chapter 1 of this title shall identify management practices which will carry out the policies of this Act and will accomplish the purposes for which the concerned National Park System unit was established or expanded and shall include at least the following:"],[1,"(1) Maps indicating areas of particular importance as to wilderness, natural, historical, wildlife, cultural, archeological, paleontological, geological, recreational, and similar resources and also indicating the areas into which such unit will be divided for administrative purposes."],[1,"(2) A description of the programs and methods that will be employed to manage fish and wildlife resources and habitats, cultural, geological, recreational, and wilderness resources, and how each conservation system unit will contribute to overall resources management goals of that region. Such programs should include research, protection, restoration, development, and interpretation as appropriate."],[1,"(3) A description of any areas of potential or proposed development, indicating types of visitor services and facilities to be provided, the estimated costs of such services and facilities, and whether or not such services and facilities could and should be provided outside the boundaries of such unit."],[1,"(4) A plan for access to, and circulation within, such unit, indicating the type and location of transportation routes and facilities, if any."],[1,"(5) A description of the programs and methods which the Secretary plans to use for the purposes of (A) encouraging the recognition and protection of the culture and history of the individuals residing, on December 2, 1980, in such unit and areas in the vicinity of such unit, and (B) providing and encouraging employment of such individuals."],[1,"(6) A plan for acquiring land with respect to such unit, including proposed modifications in the boundaries of such unit."],[1,"(7) A description (A) of privately owned areas, if any, which are within such unit, (B) of activities carried out in, or proposed for, such areas, (C) of the present and potential effects of such activities on such unit, (D) of the purposes for which such areas are used, and (E) of methods (such as cooperative agreements and issuance or enforcement of regulations) of controlling the use of such activities to carry out the policies of this Act and the purposes for which such unit is established or expanded."],[1,"(8) A plan indicating the relationship between the management of such unit and activities being carried out in, or proposed for, surrounding areas and also indicating cooperative agreements which could and should be entered into for the purpose of improving such management."],[0,"(c) Consideration of factors"],[0,"In developing, preparing, and revising a plan under this section the Secretary shall take into consideration at least the following factors:"],[1,"(1) The specific purposes for which the concerned conservation system unit was established or expanded."],[1,"(2) Protection and preservation of the ecological, environmental, wildlife, cultural, historical, archeological, geological, recreational, wilderness, and scenic character of the concerned unit and of areas in the vicinity of such unit."],[1,"(3) Providing opportunities for Alaska Natives residing in the concerned unit and areas adjacent to such unit to continue performing in such unit activities which they have traditionally or historically performed in such unit."],[1,"(4) Activities being carried out in areas adjacent to, or surrounded by, the concerned unit."],[0,"(d) Hearing and participation"],[0,"In developing, preparing, and revising a plan under this section the Secretary shall hold at least one public hearing in the vicinity of the concerned conservation unit, hold at least one public hearing in a metropolitan area of Alaska, and, to the extent practicable, permit the following persons to participate in the development, preparation, and revision of such plan:"],[1,"(1) The Alaska Land Use Council and officials of Federal agencies whose activities will be significantly affected by implementation of such plan."],[1,"(2) Officials of the State and of political subdivisions of the State whose activities will be significantly affected by implementation of such plan."],[1,"(3) Officials of Native Corporations which will be significantly affected by implementation of such plan."],[1,"(4) Concerned local, State, and National organizations and interested individuals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/3191?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3191. Management plans","tname":"Conservation","by":{"1":"9, 43","2":"9, 10"}},{"t":"usc","label":"16 U.S.C. § 3201","url":"https://www.law.cornell.edu/uscode/text/16/3201","stext":{"head":"§3201. Administration of national preserves","paras":[[0,"A National Preserve in Alaska shall be administered and managed as a unit of the National Park System in the same manner as a national park except as otherwise provided in this Act and except that the taking of fish and wildlife for sport purposes and subsistence uses, and trapping shall be allowed in a national preserve under applicable State and Federal law and regulation. Consistent with the provisions of section 3126 of this title, within national preserves the Secretary may designate zones where and periods when no hunting, fishing, trapping, or entry may be permitted for reasons of public safety, administration, floral and faunal protection, or public use and enjoyment. Except in emergencies, any regulations prescribing such restrictions relating to hunting, fishing, or trapping shall be put into effect only after consultation with the appropriate State agency having responsibility over hunting, fishing, and trapping activities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/3201?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3201. Administration of national preserves","tname":"Conservation","by":{"1":"43","2":"3"}},{"t":"usc","label":"16 U.S.C. § 3203","url":"https://www.law.cornell.edu/uscode/text/16/3203","subs":["(b)"],"by":{"1":"44"}},{"t":"usc","label":"16 U.S.C. § 3204","url":"https://www.law.cornell.edu/uscode/text/16/3204","by":{"1":"43"}},{"t":"usc","label":"43 U.S.C. § 1603","url":"https://www.law.cornell.edu/uscode/text/43/1603","subs":["(b)"],"by":{"1":"4"}},{"t":"usc","label":"43 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/43/1605","stext":{"head":"§1605. Alaska Native Fund","paras":[[0,"(a) Establishment in Treasury; deposits into Fund of general fund, interest, and revenue sharing moneys"],[0,"There is hereby established in the United States Treasury an Alaska Native Fund into which the following moneys shall be deposited:"],[1,"(1) $462,500,000 from the general fund of the Treasury, which are authorized to be appropriated according to the following schedule:"],[2,"(A) $12,500,000 during the fiscal year in which this chapter becomes effective;"],[2,"(B) $50,000,000 during the second fiscal year;"],[2,"(C) $70,000,000 during each of the third, fourth, and fifth fiscal years;"],[2,"(D) $40,000,000 during the period beginning July 1, 1976, and ending September 30, 1976; and"],[2,"(E) $30,000,000 during each of the next five fiscal years, for transfer to the Alaska Native Fund in the fourth quarter of each fiscal year."],[1,"(2) Four percent interest per annum, which is authorized to be appropriated, on any amount authorized to be appropriated by this paragraph that is not appropriated within six months after the fiscal year in which payable."],[1,"(3) $500,000,000 pursuant to the revenue sharing provisions of section 1608 of this title."],[0,"(b) Prohibition of expenditures for propaganda or political campaigns; misdemeanor; penalty"],[0,"None of the funds paid or distributed pursuant to this section to any of the Regional and Village Corporations established pursuant to this chapter shall be expended, donated, or otherwise used for the purpose of carrying on propaganda, or intervening in (including the publishing and distributing of statements) any political campaign on behalf of any candidate for public office. Any person who willfully violates the foregoing provision shall be guilty of a misdemeanor and, upon conviction thereof, shall be fined not more than $1,000 or imprisoned not more than twelve months, or both."],[0,"(c) Distribution of Fund moneys among organized Regional Corporations; basis as relative number of Native enrollees in each region; reserve for payment of attorney and other fees; retention of share in Fund until organization of corporation"],[0,"After completion of the roll prepared pursuant to section 1604 of this title, all money in the Fund, except money reserved as provided in section 1619 of this title for the payment of attorney and other fees, shall be distributed at the end of each three months of the fiscal year among the Regional Corporations organized pursuant to section 1606 of this title on the basis of the relative numbers of Natives enrolled in each region. The share of a Regional Corporation that has not been organized shall be retained in the Fund until the Regional Corporation is organized."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/43/1605?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1605. Alaska Native Fund","tname":"Public Lands","by":{"1":"4"}},{"t":"usc","label":"43 U.S.C. § 1610","url":"https://www.law.cornell.edu/uscode/text/43/1610","by":{"1":"4"}},{"t":"law","label":"Alaska Statehood Act, Pub. L. No. 85-508","url":"https://www.govinfo.gov/link/statute/72/339","by":{"1":"4"}},{"t":"usc","label":"16 U.S.C. § 431","url":"https://www.law.cornell.edu/uscode/text/16/431","by":{"1":"5"}},{"t":"law","label":"Pub. L. No. 104-134","url":"https://www.govinfo.gov/link/plaw/104/public/134","by":{"1":"10, 38","2":"16"}},{"t":"law","label":"Pub. L. No. 105-83","url":"https://www.govinfo.gov/link/plaw/105/public/83","by":{"1":"10, 38"}},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"1":"10, 38","2":"16"}},{"t":"usc","label":"43 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/43/1301","by":{"1":"4"}},{"t":"usc","label":"16 U.S.C. § 1271","url":"https://www.law.cornell.edu/uscode/text/16/1271","stext":{"head":"§1271. Congressional declaration of policy","paras":[[0,"It is hereby declared to be the policy of the United States that certain selected rivers of the Nation which, with their immediate environments, possess outstandingly remarkable scenic, recreational, geologic, fish and wildlife, historic, cultural, or other similar values, shall be preserved in free-flowing condition, and that they and their immediate environments shall be protected for the benefit and enjoyment of present and future generations. The Congress declares that the established national policy of dam and other construction at appropriate sections of the rivers of the United States needs to be complemented by a policy that would preserve other selected rivers or sections thereof in their free-flowing condition to protect the water quality of such rivers and to fulfill other vital national conservation purposes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1271?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1271. Congressional declaration of policy","tname":"Conservation","by":{"1":"42","2":"11"}},{"t":"usc","label":"16 U.S.C. § 1281","url":"https://www.law.cornell.edu/uscode/text/16/1281","subs":["(a)","(c)"],"by":{"1":"21, 43, 43"}},{"t":"usc","label":"16 U.S.C. § 1a-1","url":"https://www.law.cornell.edu/uscode/text/16/1a-1","by":{"1":"7"}},{"t":"reg","label":"33 C.F.R. § 2.38","url":"https://www.ecfr.gov/current/title-33/section-2.38","by":{"1":"25"}},{"t":"reg","label":"50 C.F.R. § 100.3","url":"https://www.ecfr.gov/current/title-50/section-100.3","subs":["(b)"],"by":{"1":"10, 36"}},{"t":"reg","label":"34 Fed. Reg. 1025","url":"https://www.govinfo.gov/link/fr/34/1025","by":{"1":"4"}},{"t":"reg","label":"48 Fed. Reg. 30,252","url":"https://www.govinfo.gov/link/fr/48/30252","by":{"1":"13, 29","2":"3"}},{"t":"reg","label":"59 Fed. Reg. 65,948","url":"https://www.govinfo.gov/link/fr/59/65948","by":{"1":"12, 56, 57","2":"8"}},{"t":"reg","label":"61 Fed. Reg. 35,133","url":"https://www.govinfo.gov/link/fr/61/35133","by":{"1":"11, 23, 56"}},{"t":"reg","label":"62 Fed. Reg. 66,216","url":"https://www.govinfo.gov/link/fr/62/66216","by":{"1":"10, 36"}},{"t":"reg","label":"64 Fed. Reg. 1276","url":"https://www.govinfo.gov/link/fr/64/1276","by":{"1":"10, 36, 38, 57"}},{"t":"case","label":"American Exp. Co. v. Italian Colors Restaurant","cite":"570 U.S. 228","y":2013,"id":"2012/12-133","sc":1,"sum":"The Court held that a clause prohibiting class action suits was enforceable even though it would cause costly arbitration.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Conn. Nat. Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Cited Authorities Page Kohl Indus. Park Co. v. Rockland County","cite":"710 F.2d 895","y":1983,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/710/895/","by":{"2":"19"}},{"t":"case","label":"Louisiana Pub. Serv. Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Miller v. Johnson","cite":"515 U.S. 900","y":1995,"id":"1994/94-631","sc":1,"sum":"In some instances, a reapportionment plan may be so highly irregular and bizarre in shape that it rationally cannot be understood as anything other than an effort to segregate voters based on race. Applying the rule laid down in Shaw v. Reno requires strict scrutiny whenever race is the \"overriding, predominant force\" in the redistricting process.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"O’Gilvie v. United States","cite":"519 U.S. 79","y":1996,"id":"1996/95-966","sc":1,"sum":"The Court held that the punitive damages received by the O'Gilvies were not received \"on account of\" personal injuries,\" and therefore the provision did not apply and the damages were taxable.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"v Cited Authorities Page United States v. Estate of Romani","cite":"523 U.S. 517","y":1998,"id":"1997/96-1613","sc":1,"sum":"The Court held that section 3713(a) does not require that a federal tax claim be given preference over a judgment creditor's perfected lien on real property.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"usc","label":"16 U.S.C. § 1274","url":"https://www.law.cornell.edu/uscode/text/16/1274","stext":{"head":"§1274. Component rivers and adjacent lands","paras":[[0,"(a) Designation"],[0,"The following rivers and the land adjacent thereto are hereby designated as components of the national wild and scenic rivers system:"],[0,"(1) Clearwater, Middle Fork, Idaho—The Middle Fork from the town of Kooskia upstream to the town of Lowell; the Lochsa River from its junction with the Selway at Lowell forming the Middle Fork, upstream to the Powell Ranger Station; and the Selway River from Lowell upstream to its origin; to be administered by the Secretary of Agriculture."],[0,"(2) Eleventh Point, Missouri—The segment of the river extending downstream from Thomasville to State Highway 142; to be administered by the Secretary of Agriculture."],[0,"(3) Feather, California—The entire Middle Fork downstream from the confluence of its tributary streams one kilometer south of Beckwourth, California; to be administered by the Secretary of Agriculture."],[0,"(4) Rio Grande, New Mexico—The segment extending from the Colorado State line downstream to the State Highway 96 crossing, and the lower four miles of the Red River; to be administered by the Secretary of the Interior."],[0,"(5) Rogue, oregon.—"],[1,"(A) In general.—The segment of the river extending from the mouth of the Applegate River downstream to the Lobster Creek Bridge, to be administered by the Secretary of the Interior or the Secretary of Agriculture, as agreed to by the Secretaries of the Interior and Agriculture or as directed by the President."],[1,"(B) Additions.—In addition to the segment described in subparagraph (A), there are designated the following segments in the Rogue River:"],[2,"(i) Kelsey creek.—The approximately 6.8-mile segment of Kelsey Creek from the Wild Rogue Wilderness boundary in T. 32 S., R. 9 W., sec. 25, Willamette Meridian, to the confluence with the Rogue River, as a wild river."],[2,"(ii) East fork kelsey creek.—"],[3,"(I) Scenic river.—The approximately 0.2-mile segment of East Fork Kelsey Creek from headwaters downstream to the Wild Rogue Wilderness boundary in T. 33 S., R. 8 W., sec. 5, Willamette Meridian, as a scenic river."],[3,"(II) Wild river.—The approximately 4.6-mile segment of East Fork Kelsey Creek from the Wild Rogue Wilderness boundary in T. 33 S., R. 8 W., sec. 5, Willamette Meridian, to the confluence with Kelsey Creek, as a wild river."],[2,"(iii) Whisky creek.—"],[3,"(I) Recreational river.—The approximately 1.6-mile segment of Whisky Creek from the confluence of the East Fork and West Fork to the south boundary of the non-Federal land in T. 33 S., R. 8 W., sec. 17, Willamette Meridian, as a recreational river."],[3,"(II) Wild river.—The approximately 1.2-mile segment of Whisky Creek from road 33–8–23 to the confluence with the Rogue River, as a wild river."],[2,"(iv) East fork whisky creek.—"],[3,"(I) Scenic river.—The approximately 0.9-mile segment of East Fork Whisky Creek from its headwaters to Wild Rogue Wilderness boundary in T. 33 S., R. 8 W., sec. 11, Willamette Meridian, as a scenic river."],[3,"(II) Wild river.—The approximately 2.6-mile segment of East Fork Whisky Creek from the Wild Rogue Wilderness boundary in T. 33 S., R. 8 W., sec. 11, Willamette Meridian, downstream to road 33–8–26 crossing, as a wild river."],[3,"(III) Recreational river.—The approximately 0.3-mile segment of East Fork Whisky Creek from road 33–8–26 to the confluence with Whisky Creek, as a recreational river."],[2,"(v) West fork whisky creek.—The approximately 4.8-mile segment of West Fork Whisky Creek from its headwaters to the confluence with the East Fork Whisky Creek, as a wild river."],[2,"(vi) Big windy creek.—"],[3,"(I) Scenic river.—The approximately 1.5-mile segment of Big Windy Creek from its headwaters to road 34–9–17.1, as a scenic river."],[3,"(II) Wild river.—The approximately 5.8-mile segment of Big Windy Creek from road 34–9–17.1 to the confluence with the Rogue River, as a wild river."],[2,"(vii) East fork big windy creek.—"],[3,"(I) Scenic river.—The approximately 0.2-mile segment of East Fork Big Windy Creek from its headwaters to road 34–8–36, as a scenic river."],[3,"(II) Wild river.—The approximately 3.7-mile segment of East Fork Big Windy Creek from road 34–8–36 to the confluence with Big Windy Creek, as a wild river."],[2,"(viii) Little windy creek.—"],[3,"(I) Scenic river.—The approximately 1.2-mile segment of Little Windy Creek from its headwaters to the Wild Rogue Wilderness boundary in T. 33 S., R. 9 W., sec. 33, Willamette Meridian, as a scenic river."],[3,"(II) Wild river.—The approximately 1.9-mile segment of Little Windy Creek from the Wild Rogue Wilderness boundary in T. 33 S., R. 9 W., sec. 34, Willamette Meridian, to the confluence with the Rogue River, as a wild river."],[2,"(ix) Howard creek.—"],[3,"(I) Scenic river.—The approximately 3.5-mile segment of Howard Creek from its headwaters to road 34–9–34, as a scenic river."],[3,"(II) Wild river.—The approximately 6.9-mile segment of Howard Creek from 0.1 miles downstream of road 34–9–34 to the confluence with the Rogue River, as a wild river."],[3,"(III) Wild river.—The approximately 3.5-mile segment of Anna Creek from its headwaters to the confluence with Howard Creek, as a wild river."],[2,"(x) Mule creek.—"],[3,"(I) Scenic river.—The approximately 3.5-mile segment of Mule Creek from its headwaters downstream to the Wild Rogue Wilderness boundary as a scenic river."],[3,"(II) Wild river.—The approximately 7.8-mile segment of Mule Creek from the Wild Rogue Wilderness boundary in T. 32 S., R. 9 W., sec. 29, Willamette Meridian, to the confluence with the Rogue River, as a wild river."],[2,"(xi) Missouri creek.—"],[3,"(I) Scenic river.—The approximately 3.1-mile segment of Missouri Creek from its headwaters downstream to the Wild Rogue Wilderness boundary in T. 33 S., R. 10 W., sec. 24, Willamette Meridian, as a scenic river."],[3,"(II) Wild river.—The approximately 1.6-mile segment of Missouri Creek from the Wild Rogue Wilderness boundary in T. 33 S., R. 10 W., sec. 24, Willamette Meridian, to the confluence with the Rogue River, as a wild river."],[2,"(xii) Jenny creek.—"],[3,"(I) Scenic river.—The approximately 3.1-mile segment of Jenny Creek from its headwaters downstream to the Wild Rogue Wilderness boundary in T. 33 S., R. 9 W., sec. 28, Willamette Meridian, as a scenic river."],[3,"(II) Wild river.—The approximately 1.8-mile segment of Jenny Creek from the Wild Rogue Wilderness boundary in T. 33 S., R. 9 W., sec. 28, Willamette Meridian, to the confluence with the Rogue River, as a wild river."],[2,"(xiii) Rum creek.—"],[3,"(I) Scenic river.—The approximately 2.2-mile segment of Rum Creek from its headwaters to the Wild Rogue Wilderness boundary in T. 34 S., R. 8 W., sec. 9, Willamette Meridian, as a scenic river."],[3,"(II) Wild river.—The approximately 2.2-mile segment of Rum Creek from the Wild Rogue Wilderness boundary in T. 34 S., R. 8 W., sec. 9, Willamette Meridian, to the confluence with the Rogue River, as a wild river."],[2,"(xiv) East fork rum creek.—"],[3,"(I) Scenic river.—The approximately 0.8-mile segment of East Fork Rum Creek from its headwaters to the Wild Rogue Wilderness boundary in T. 34 S., R. 8 W., sec. 10, Willamette Meridian, as a scenic river."],[3,"(II) Wild river.—The approximately 1.3-mile segment of East Fork Rum Creek from the Wild Rogue Wilderness boundary in T. 34 S., R. 8 W., sec. 10, Willamette Meridian, to the confluence with Rum Creek, as a wild river."],[2,"(xv) Wildcat creek.—The approximately 1.7-mile segment of Wildcat Creek from its headwaters downstream to the confluence with the Rogue River, as a wild river."],[2,"(xvi) Montgomery creek.—The approximately 1.8-mile segment of Montgomery Creek from its headwaters downstream to the confluence with the Rogue River, as a wild river."],[2,"(xvii) Hewitt creek.—"],[3,"(I) Scenic river.—The approximately 1.4-mile segment of Hewitt Creek from its headwaters to the Wild Rogue Wilderness boundary in T. 33 S., R. 9 W., sec. 19, Willamette Meridian, as a scenic river."],[3,"(II) Wild river.—The approximately 1.2-mile segment of Hewitt Creek from the Wild Rogue Wilderness boundary in T. 33 S., R. 9 W., sec. 19, Willamette Meridian, to the confluence with the Rogue River, as a wild river."],[2,"(xviii) Bunker creek.—The approximately 6.6-mile segment of Bunker Creek from its headwaters to the confluence with the Rogue River, as a wild river."],[2,"(xix) Dulog creek.—"],[3,"(I) Scenic river.—The approximately 0.8-mile segment of Dulog Creek from its headwaters to 0.1 miles downstream of road 34–8–36, as a scenic river."],[3,"(II) Wild river.—The approximately 1.0-mile segment of Dulog Creek from road 34–8–36 to the confluence with the Rogue River, as a wild river."],[2,"(xx) Quail creek.—The approximately 1.7-mile segment of Quail Creek from the Wild Rogue Wilderness boundary in T. 33 S., R. 10 W., sec. 1, Willamette Meridian, to the confluence with the Rogue River, as a wild river."],[2,"(xxi) Meadow creek.—The approximately 4.1-mile segment of Meadow Creek from its headwaters to the confluence with the Rogue River, as a wild river."],[2,"(xxii) Russian creek.—The approximately 2.5-mile segment of Russian Creek from the Wild Rogue Wilderness boundary in T. 33 S., R. 8 W., sec. 20, Willamette Meridian, to the confluence with the Rogue River, as a wild river."],[2,"(xxiii) Alder creek.—The approximately 1.2-mile segment of Alder Creek from its headwaters to the confluence with the Rogue River, as a wild river."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1274?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1274. Component rivers and adjacent lands","tname":"Conservation","by":{"2":"11, 15"}},{"t":"usc","label":"16 U.S.C. § 1284","url":"https://www.law.cornell.edu/uscode/text/16/1284","by":{"2":"11"}},{"t":"usc","label":"16 U.S.C. § 1285b","url":"https://www.law.cornell.edu/uscode/text/16/1285b","by":{"2":"11"}},{"t":"usc","label":"16 U.S.C. § 4601-22","url":"https://www.law.cornell.edu/uscode/text/16/4601-22","by":{"2":"8"}},{"t":"law","label":"Pub. L. No. 96-487","by":{"2":"13"}},{"t":"law","label":"Pub. L. No. 98-506","by":{"2":"8"}}]};